class Solution {
  private java.util.Map<Integer, TreeNode> roots;
  private java.util.Set<Integer> leaves;

  public TreeNode canMerge(java.util.List<TreeNode> trees) {
    roots = new java.util.HashMap<>();
    leaves = new java.util.HashSet<>();
    for (TreeNode t : trees) {
      roots.put(t.val, t);
      if (t.left != null) leaves.add(t.left.val);
      if (t.right != null) leaves.add(t.right.val);
    }
    TreeNode root = null;
    for (TreeNode t : trees)
      if (!leaves.contains(t.val)) {
        if (root != null) return null;
        root = t;
      }
    if (root == null) return null;
    roots.remove(root.val);
    if (!merge(root, Integer.MIN_VALUE, Integer.MAX_VALUE)) return null;
    return roots.isEmpty() ? root : null;
  }

  private boolean merge(TreeNode node, int low, int high) {
    if (node == null) return true;
    if (node.val <= low || node.val >= high) return false;
    if (node.left == null && node.right == null && roots.containsKey(node.val)) {
      TreeNode t = roots.remove(node.val);
      node.left = t.left;
      node.right = t.right;
    }
    return merge(node.left, low, node.val) && merge(node.right, node.val, high);
  }
}
